"""
Analyze aggregated end-to-end results and build a Slack report.

Consumes the ``failures.json`` / ``fixme_tests.json`` files produced by
``extract_e2e_test_results.py`` across several runs and browsers, identifies
tests that fail often enough to be flaky candidates, and formats the summary
as a Slack Block Kit message.
"""

from __future__ import annotations

import json
import os
import sys
from pathlib import Path

# The Playwright config runs every spec against these three browsers, so a
# single logical run produces up to ``NUM_BROWSERS`` executions per test.
BROWSERS = ("chromium", "firefox", "webkit")
NUM_BROWSERS = len(BROWSERS)

# Minimum share of executions that must fail before a test is worth flagging.
MIN_FAILURE_RATE = 0.05

SLACK_CHANNEL = "airflow-3-ui"


def escape_slack_mrkdwn(text: str) -> str:
    """Escape the characters Slack's mrkdwn treats specially.

    ``&`` must be escaped first so the ``&`` introduced by the ``<``/``>``
    replacements is not double-escaped.
    """
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def _failure_count(info) -> int:
    """Best-effort count of how many times a test failed, given varied shapes."""
    if isinstance(info, bool):
        return int(info)
    if isinstance(info, int):
        return info
    if isinstance(info, float):
        return int(info)
    if isinstance(info, list):
        return len(info)
    if isinstance(info, dict):
        for key in ("count", "failures", "failure_count", "num_failures", "total_failures", "total", "failed"):
            value = info.get(key)
            if isinstance(value, bool):
                continue
            if isinstance(value, int):
                return value
            if isinstance(value, list):
                return len(value)
        browsers = info.get("browsers")
        if isinstance(browsers, dict):
            total = sum(v for v in browsers.values() if isinstance(v, int) and not isinstance(v, bool))
            if total:
                return total
        if isinstance(browsers, list):
            return len(browsers)
        runs = info.get("runs")
        if isinstance(runs, list):
            return len(runs)
    return 0


def _error_text(info) -> str:
    """Best-effort extraction of a representative error message."""
    if isinstance(info, str):
        return info
    if isinstance(info, dict):
        for key in ("last_error", "error", "message"):
            value = info.get(key)
            if isinstance(value, str) and value:
                return value
        for key in ("errors", "failures"):
            items = info.get(key)
            if isinstance(items, list) and items:
                last = items[-1]
                if isinstance(last, str) and last:
                    return last
                if isinstance(last, dict):
                    return str(last.get("error") or last.get("message") or "")
    if isinstance(info, list) and info:
        last = info[-1]
        if isinstance(last, str):
            return last
        if isinstance(last, dict):
            return str(last.get("error") or last.get("message") or "")
    return ""


def identify_flaky_candidates(failures_by_test: dict, runs_with_data: int) -> list:
    """Return tests whose failure rate exceeds the minimum threshold.

    The failure rate is computed against the total number of executions
    (``runs_with_data`` runs times ``NUM_BROWSERS`` browsers). Tests below
    ``MIN_FAILURE_RATE`` (e.g. a single failure over ten runs and three
    browsers) are excluded. Results are sorted by failure rate, highest first.
    """
    if not failures_by_test or not runs_with_data:
        return []

    total_executions = runs_with_data * NUM_BROWSERS
    candidates = []
    for test_name, info in failures_by_test.items():
        failures = _failure_count(info)
        if failures <= 0:
            continue
        failure_rate = failures / total_executions
        if failure_rate < MIN_FAILURE_RATE:
            continue
        candidates.append(
            {
                "test": str(test_name),
                "failures": failures,
                "failure_rate": failure_rate,
            }
        )

    candidates.sort(key=lambda candidate: candidate["failure_rate"], reverse=True)
    return candidates


def _fixme_names(fixme_tests) -> list:
    """Return the fixme test names regardless of the container shape."""
    if isinstance(fixme_tests, dict):
        return [str(name) for name in fixme_tests]
    if isinstance(fixme_tests, list):
        names = []
        for item in fixme_tests:
            if isinstance(item, dict):
                names.append(str(item.get("test", item)))
            else:
                names.append(str(item))
        return names
    return []


def _section(text: str) -> dict:
    return {"type": "section", "text": {"type": "mrkdwn", "text": text}}


